const { RangeTree } = require('./src/range-tree');
let seed = 12345;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;

for (let trial = 0; trial < 300; trial++) {
  const n = 1 + Math.floor(rnd() * 40);
  const ref = Array.from({ length: n }, () => Math.floor(rnd() * 41) - 20);
  const tree = new RangeTree(ref);
  for (let op = 0; op < 200; op++) {
    const l = Math.floor(rnd() * (n + 1));
    const r = l + Math.floor(rnd() * (n - l + 1));
    const v = Math.floor(rnd() * 41) - 20;
    const kind = rnd();
    if (kind < 0.3) { tree.assign(l, r, v); for (let i = l; i < r; i++) ref[i] = v; }
    else if (kind < 0.6) { tree.add(l, r, v); for (let i = l; i < r; i++) ref[i] += v; }
    else if (kind < 0.7) {
      const s = tree.sum(l, r);
      const rs = ref.slice(l, r).reduce((a, b) => a + b, 0);
      if (s !== rs) throw new Error('sum ' + s + ' != ' + rs);
    } else if (kind < 0.8) {
      const m = tree.max(l, r);
      const rm = ref.slice(l, r).reduce((a, b) => Math.max(a, b), -Infinity);
      if (m !== rm) throw new Error('max ' + m + ' != ' + rm);
    } else if (kind < 0.9) {
      const lo = Math.floor(rnd() * (n + 1));
      const x = Math.floor(rnd() * 45) - 22;
      const f = tree.firstAtLeast(lo, x);
      let rf = -1;
      for (let i = lo; i < n; i++) if (ref[i] >= x) { rf = i; break; }
      if (f !== rf) throw new Error('first ' + f + ' != ' + rf);
    } else {
      const i = Math.floor(rnd() * n);
      if (tree.get(i) !== ref[i]) throw new Error('get mismatch');
    }
  }
  const arr = tree.toArray();
  if (JSON.stringify(arr) !== JSON.stringify(ref)) throw new Error('toArray mismatch');
  if (tree.length !== n) throw new Error('length mismatch');
}

